import{_ as r,o,c as a,al as t}from"./chunks/framework.7vp1BMOE.js";const u=JSON.parse('{"title":"Hiwonder 4-Channel Encoder Motor Module","description":"","frontmatter":{},"headers":[],"relativePath":"uk/peripherals/hiwonder_emm.md","filePath":"uk/peripherals/hiwonder_emm.md"}'),i={name:"uk/peripherals/hiwonder_emm.md"};function n(d,e,s,l,h,c){return o(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="hiwonder-4-channel-encoder-motor-module" tabindex="-1">Hiwonder 4-Channel Encoder Motor Module <a class="header-anchor" href="#hiwonder-4-channel-encoder-motor-module" aria-label="Permalink to &quot;Hiwonder 4-Channel Encoder Motor Module&quot;">​</a></h1><p>The <a href="https://www.hiwonder.com/products/4-channel-encoder-motor-driver" target="_blank" rel="noreferrer">Hiwonder 4-Channel Encoder Motor Driver</a> is a small I2C motor controller with integrated encoder feedback for up to four brushed DC motors. It is well suited to small wheeled rovers (differential, ackermann, or mecanum) where size, weight, and a low channel count make a full-size ESC overkill.</p><p>PX4 supports the board via the <a href="./../modules/modules_driver#hiwonder-emm"><code>hiwonder_emm</code></a> I2C driver.</p><h2 id="функціі" tabindex="-1">Функції <a class="header-anchor" href="#функціі" aria-label="Permalink to &quot;Функції&quot;">​</a></h2><ul><li>Four independent motor outputs with closed-loop speed control from on-board encoders.</li><li>I2C interface (default address <code>0x34</code>, 400 kHz).</li><li>Battery voltage telemetry of the supply rail powering the motor outputs.</li><li>Selectable motor types (TT, N20, JGB37-520-12V-110RPM, or open-loop &quot;no encoder&quot;).</li></ul><h2 id="де-купити" tabindex="-1">Де купити <a class="header-anchor" href="#де-купити" aria-label="Permalink to &quot;Де купити&quot;">​</a></h2><ul><li><a href="https://www.hiwonder.com/products/4-channel-encoder-motor-driver" target="_blank" rel="noreferrer">Hiwonder — 4-Channel Encoder Motor Driver product page</a></li></ul><h2 id="налаштування-програмного-забезпечення" tabindex="-1">Налаштування програмного забезпечення <a class="header-anchor" href="#налаштування-програмного-забезпечення" aria-label="Permalink to &quot;Налаштування програмного забезпечення&quot;">​</a></h2><h3 id="підключення" tabindex="-1">Підключення <a class="header-anchor" href="#підключення" aria-label="Permalink to &quot;Підключення&quot;">​</a></h3><p>Connect the four motors (with their encoder leads) to channels <code>M1</code>–<code>M4</code> on the EMM and supply the motor driver from a battery suitable for the motors used. Wire the EMM&#39;s I2C bus (<code>SDA</code>, <code>SCL</code>, <code>GND</code>) to an external I2C port on the flight controller. The driver is hard-coded to bus <code>1</code> (the first external I2C bus) at address <code>0x34</code>, which is the board default.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The driver auto-detects the four channels but the motor type is selected in firmware. The shipped default is <code>JGB37-520-12V-110RPM</code>; change <a href="https://github.com/PX4/PX4-Autopilot/blob/main/src/drivers/hiwonder_emm/HiwonderEMM.cpp" target="_blank" rel="noreferrer"><code>HiwonderEMM.cpp</code></a> (<code>set_motor_type</code>) if you use a different model.</p></div><h2 id="збірка-прошивки" tabindex="-1">Збірка прошивки <a class="header-anchor" href="#збірка-прошивки" aria-label="Permalink to &quot;Збірка прошивки&quot;">​</a></h2><p>To use the EMM, the <code>hiwonder_emm</code> driver must be compiled into the firmware and started on boot.</p><ol><li><p>Add the following line to the <code>rover.px4board</code> file of your board (for Skynode S this would be in <a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/auterion/fmu-v6s/rover.px4board" target="_blank" rel="noreferrer">boards/auterion/fmu-v6s/rover.px4board</a>) so the driver is compiled in:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CONFIG_DRIVERS_HIWONDER_EMM=y</span></span></code></pre></div></li><li><p>Make sure the driver is started on boot when the <a href="./../advanced_config/parameter_reference#HIWONDER_EMM_EN">HIWONDER_EMM_EN</a> parameter is <code>1</code>.</p><p>For rover airframes (ackermann, differential, mecanum) this is already done by the shared rover startup script <a href="https://github.com/PX4/PX4-Autopilot/blob/main/ROMFS/px4fmu_common/init.d/rc.rover" target="_blank" rel="noreferrer"><code>rc.rover</code></a>, which contains:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> param</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compare</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> HIWONDER_EMM_EN</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">then</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">   hiwonder_emm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">fi</span></span></code></pre></div><p>For other airframes that should use the EMM, add the same block to your board&#39;s <code>rc.board_sensors</code> file (for Skynode S this would be in <a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/auterion/fmu-v6s/init/rc.board_sensors" target="_blank" rel="noreferrer">boards/auterion/fmu-v6s/init/rc.board_sensors</a>).</p></li><li><p>Build and flash the firmware for your board.</p></li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Many flight controllers already enable <code>CONFIG_DRIVERS_HIWONDER_EMM=y</code> in their <code>rover.px4board</code> configuration, so the default rover build is sufficient and step 1 is not required.</p></div><h2 id="налаштування-польотного-контролера" tabindex="-1">Налаштування польотного контролера <a class="header-anchor" href="#налаштування-польотного-контролера" aria-label="Permalink to &quot;Налаштування польотного контролера&quot;">​</a></h2><h3 id="enable-the-driver" tabindex="-1">Enable the Driver <a class="header-anchor" href="#enable-the-driver" aria-label="Permalink to &quot;Enable the Driver&quot;">​</a></h3><p>Set the <a href="./../advanced_config/parameter_reference#HIWONDER_EMM_EN">HIWONDER_EMM_EN</a> parameter to <code>1</code> and reboot. On the next boot the driver is started by the startup script (see <a href="#building-the-firmware">Building the Firmware</a>).</p><h3 id="actuator-allocation" tabindex="-1">Actuator Allocation <a class="header-anchor" href="#actuator-allocation" aria-label="Permalink to &quot;Actuator Allocation&quot;">​</a></h3><p>The driver exposes a four-channel output group with the <code>EMM</code> parameter prefix. In <a href="./../config/actuators">Actuator Configuration</a>, assign the rover wheel outputs (e.g. <code>Motor 1</code>, <code>Motor 2</code>, …) to channels <code>EMM 1</code>–<code>EMM 4</code> matching how the motors are wired to the EMM.</p><p>The output range is fixed in firmware to <code>0..255</code> (the EMM&#39;s protocol range, internally mapped to a signed <code>[-128, 127]</code> speed command — <code>128</code> is stop, values below are reverse, values above are forward). <code>EMM_DIS{i}</code> (disarmed) and <code>EMM_FAIL{i}</code> (failsafe) per-channel parameters are user-tunable in the standard range.</p><h2 id="підтримувані-транспортні-засоби" tabindex="-1">Підтримувані транспортні засоби <a class="header-anchor" href="#підтримувані-транспортні-засоби" aria-label="Permalink to &quot;Підтримувані транспортні засоби&quot;">​</a></h2><p>The EMM is used on the reference Hiwonder rover frames:</p><ul><li><code>50002</code> — Hiwonder differential rover</li><li><code>51003</code> — Hiwonder ackermann rover</li><li><code>52001</code> — Hiwonder mecanum rover</li></ul><p>See <a href="./../frames_rover/">Rovers</a> for vehicle-side configuration.</p><h2 id="подальша-інформація" tabindex="-1">Подальша інформація <a class="header-anchor" href="#подальша-інформація" aria-label="Permalink to &quot;Подальша інформація&quot;">​</a></h2><ul><li>Driver source: <a href="https://github.com/PX4/PX4-Autopilot/tree/main/src/drivers/hiwonder_emm" target="_blank" rel="noreferrer"><code>src/drivers/hiwonder_emm</code></a></li><li><a href="./../config/actuators">Actuator Configuration</a></li><li><a href="./../frames_rover/">Марсохід</a></li></ul>`,27)])])}const m=r(i,[["render",n]]);export{u as __pageData,m as default};
